#!/usr/bin/env bash
# One-off: creates vaults/Kubernetes/items/homeassistant-timescale for the
# homeassistant role on the TimescaleDB cluster (core/timescale). The
# password is generated by 1Password and never printed.
set -euo pipefail

eval "$(op signin)"
op item create --vault Kubernetes --category login --title homeassistant-timescale \
  --generate-password='letters,digits,32' \
  username=homeassistant >/dev/null
echo "created: homeassistant-timescale"
